INSERT INTO desired_worlds SELECT value->>'id',value->>'grid',value FROM jsonb_array_elements('[{"id":"tatooine","name":"Tatooine","region":"Outer Rim Territories","grid":"R-16","x":0.6923076923076923,"y":-0.5260989010989011,"color":"#E8AD69","description":"A desert world beneath twin suns, where moisture farms and busy spaceports sit far from the centers of galactic power. Luke Skywalker’s journey begins here.","film":"A New Hope","sourceUrl":"https://www.starwars.com/databank/tatooine","uncertainty":"Schematic placement within the published Tatooine system grid; planet rendering is illustrative. Display symbol approximately traced from the supplied galaxy map within published cell R-16; not a measured planet coordinate."},{"id":"alderaan","name":"Alderaan","region":"Core Worlds","grid":"M-10","x":0.1813186813186813,"y":0.1449175824175824,"color":"#82CBDD","description":"Leia Organa’s homeworld, a place of mountains and lakes whose people valued learning and the arts. Its place in the story connects the heart of the Core to the growing rebellion.","film":"A New Hope","sourceUrl":"https://www.starwars.com/databank/alderaan","uncertainty":"Schematic placement within the published Alderaan system grid; planet rendering is illustrative. Display symbol approximately traced from the supplied galaxy map within published cell M-10; not a measured planet coordinate."},{"id":"yavin","name":"Yavin 4","region":"Outer Rim Territories","grid":"P-6","x":0.5096153846153847,"y":0.5487637362637363,"color":"#9FCB85","description":"A jungle-covered moon of the gas giant Yavin. Ancient temples shelter a Rebel base, making this remote world a gathering point for pilots, leaders, and a desperate mission.","film":"A New Hope","sourceUrl":"https://www.starwars.com/databank/yavin-4","uncertainty":"Uses the parent Yavin system grid, not an independently measured moon position; rendering is illustrative. Display symbol approximately traced from the supplied galaxy map within published cell P-6; not a measured planet coordinate."},{"id":"hoth","name":"Hoth","region":"Outer Rim Territories","grid":"K-18","x":-0.047390109890109895,"y":-0.7122252747252747,"color":"#BCDCEC","description":"A remote world of glaciers and frozen plains. The Rebel Alliance established Echo Base here, among the snowfields inhabited by tauntauns and wampas.","film":"The Empire Strikes Back","sourceUrl":"https://www.starwars.com/databank/hoth","uncertainty":"System grid K-18 also contains Bespin. planet rendering is illustrative. Display symbol approximately traced from the supplied galaxy map within published cell K-18; not a measured planet coordinate."},{"id":"dagobah","name":"Dagobah","region":"Outer Rim Territories","grid":"M-19","x":0.2135989010989011,"y":-0.8035714285714286,"color":"#87A58A","description":"Dense vegetation, mist and wetlands cover this secluded world. Its abundant life and strong connection to the Force make it a refuge for Yoda and a place of discovery for Luke.","film":"The Empire Strikes Back","sourceUrl":"https://www.starwars.com/databank/dagobah","uncertainty":"Schematic placement within the published Dagobah system grid; planet rendering is illustrative. Display symbol approximately traced from the supplied galaxy map within published cell M-19; not a measured planet coordinate."},{"id":"bespin","name":"Bespin","region":"Outer Rim Territories","grid":"K-18","x":-0.047390109890109895,"y":-0.7046703296703296,"color":"#E5B49A","description":"An immense gas giant with a habitable layer in its atmosphere. Cloud City floats among its pastel clouds, supporting a community built around gas mining.","film":"The Empire Strikes Back","sourceUrl":"https://www.starwars.com/databank/bespin","uncertainty":"System grid K-18 also contains Hoth. planet rendering is illustrative. Display symbol approximately traced from the supplied galaxy map within published cell K-18; not a measured planet coordinate."},{"id":"coruscant","name":"Coruscant","region":"Core Worlds","grid":"L-9","x":0.051000000000000004,"y":0.15384615384615385,"color":"#B8B3EC","description":"A city that covers a planet, with traffic and communities layered above and below its skyline. Coruscant is a center of government and a crossroads for people from across the galaxy.","film":"Andor · The Clone Wars","sourceUrl":"https://www.starwars.com/databank/coruscant","uncertainty":"Schematic placement within the published Coruscant system grid. Its Return of the Jedi appearance is edition-dependent; rendering is illustrative. Display symbol approximately traced from the supplied galaxy map within published cell L-9; not a measured planet coordinate. Symbol touches a grid edge; display anchor constrained inside the published cell."},{"id":"mandalore","name":"Mandalore","region":"Outer Rim Territories","grid":"O-7","x":0.4134615384615385,"y":0.42445054945054944,"color":"#87BFC0","description":"A world of inhospitable deserts, cities and a long warrior tradition. The lives of its clans connect stories in The Clone Wars with the journeys of The Mandalorian.","film":"The Clone Wars · The Mandalorian","sourceUrl":"https://www.starwars.com/databank/mandalore","uncertainty":"Schematic placement within the published Mandalore system grid. Landscape and political conditions vary by era; rendering is illustrative. Display symbol approximately traced from the supplied galaxy map within published cell O-7; not a measured planet coordinate."},{"id":"endor","name":"Endor (forest moon)","region":"Outer Rim Territories","grid":"H-16","x":-0.3,"y":-0.5,"color":"#87AB7A","description":"The forest moon is home to the Ewoks. Its map anchor represents the Endor system, not an exact moon coordinate.","film":"Return of the Jedi","sourceUrl":"https://www.starwars.com/databank/endor","uncertainty":"Parent-system placement: the official Databank identifies the forest moon and Endor system context; the appendix lists Endor at H-16 (page 16). The displayed cell center is not the moon’s precise positi