CREATE TEMP TABLE desired_sequences (id text PRIMARY KEY, payload jsonb) ON COMMIT DROP;
INSERT INTO desired_sequences SELECT value->>'id',value FROM jsonb_array_elements('[{"id":"boba-fett","title":"The Book of Boba Fett · chapter narrative order","description":"Follow all seven numbered chapters, keeping Boba’s memories and the Mandalorian interlude in their original presentation.","sourceUrl":"https://www.starwars.com/series/the-book-of-boba-fett","itemIds":["boba-fett-s01e01","boba-fett-s01e02","boba-fett-s01e03","boba-fett-s01e04","boba-fett-s01e05","boba-fett-s01e06","boba-fett-s01e07"],"caveats":["Whole-episode narrative order, not scene chronology. Flashbacks and visions remain inside their chapters.","Chapters 5–7 bridge The Mandalorian seasons 2 and 3 while retaining their Book of Boba Fett identity.","Location coverage is partial. Luke’s school is retained as an unmapped site without an inferred planetary identity."]},{"id":"rogue-one","title":"Rogue One · standalone film","description":"The complete film connects Andor with A New Hope in the official viewing guide.","sourceUrl":"https://www.starwars.com/news/star-wars-movies-and-series-guide","itemIds":["rogue-one"],"caveats":["Whole-work viewing order only; the film’s earlier scenes remain inside the film.","No exact event dates, scene interleaving, or planet-to-planet travel order is implied."]},{"id":"ahsoka","title":"Ahsoka · season 1 narrative order","description":"Follow the eight numbered parts of the complete first season, preserving visions and recalled battles inside their original episodes.","sourceUrl":"https://www.starwars.com/series/ahsoka","itemIds":["ahsoka-s01e01","ahsoka-s01e02","ahsoka-s01e03","ahsoka-s01e04","ahsoka-s01e05","ahsoka-s01e06","ahsoka-s01e07","ahsoka-s01e08"],"caveats":["Season 1 only; later seasons and announced episodes are outside this collection.","Whole-episode narrative order is not event chronology. Visions of Clone Wars battles remain in Part Five, not moved into the Clone Wars sequence.","Peridea is in another galaxy; this sequence supplies no map placement, travel distance, or exact in-universe dates."]},{"id":"clone-wars","title":"The Clone Wars · official chronological order","description":"The official whole-episode viewing sequence, including the 2008 theatrical film: 134 stories across the Clone Wars.","sourceUrl":"https://www.starwars.com/news/star-wars-the-clone-wars-chronological-episodeorder","itemIds":["clone-wars-s02e16","clone-wars-s01e16","clone-wars-film","clone-wars-s03e01","clone-wars-s03e03","clone-wars-s01e01","clone-wars-s01e02","clone-wars-s01e03","clone-wars-s01e04","clone-wars-s01e05","clone-wars-s01e06","clone-wars-s01e07","clone-wars-s01e08","clone-wars-s01e09","clone-wars-s01e10","clone-wars-s01e11","clone-wars-s01e12","clone-wars-s01e13","clone-wars-s01e14","clone-wars-s01e15","clone-wars-s01e17","clone-wars-s01e18","clone-wars-s01e19","clone-wars-s01e20","clone-wars-s01e21","clone-wars-s02e01","clone-wars-s02e02","clone-wars-s02e03","clone-wars-s02e17","clone-wars-s02e18","clone-wars-s02e19","clone-wars-s02e04","clone-wars-s02e05","clone-wars-s02e06","clone-wars-s02e07","clone-wars-s02e08","clone-wars-s02e09","clone-wars-s02e10","clone-wars-s02e11","clone-wars-s02e12","clone-wars-s02e13","clone-wars-s02e14","clone-wars-s02e20","clone-wars-s02e21","clone-wars-s02e22","clone-wars-s03e05","clone-wars-s03e06","clone-wars-s03e07","clone-wars-s03e02","clone-wars-s03e04","clone-wars-s03e08","clone-wars-s01e22","clone-wars-s03e09","clone-wars-s03e10","clone-wars-s03e11","clone-wars-s02e15","clone-wars-s03e12","clone-wars-s03e13","clone-wars-s03e14","clone-wars-s03e15","clone-wars-s03e16","clone-wars-s03e17","clone-wars-s03e18","clone-wars-s03e19","clone-wars-s03e20","clone-wars-s03e21","clone-wars-s03e22","clone-wars-s04e01","clone-wars-s04e02","clone-wars-s04e03","clone-wars-s04e04","clone-wars-s04e05","clone-wars-s04e06","clone-wars-s04e07","clone-wars-s04e08","clone-wars-s04e09","clone-wars-s04e10","clone-wars-s04e11","clone-wars-s04e12","clone-wars-s04e13","clone-wars-s04e14","clone-wars-s04e15","clone-wars-s04e16","clone-wars-s04e17","clone-wars-s04e18","clone-wars-s04e19","clone-wars-s04e20","clone-wars-s04e21","clone-wars-s04e22","clone-wars-s05e02","clone-wars-s05e03","clone-wars-s05e04","clone-wars-s05e05","clone-wars-s05e06","clone-wars-s05e07","clone-wars-s05e08","clone-wars-s05e09","clone-wars-s05e10","clone-wars-s05e11","clone-wars-s05e12","clone-wars-s05e13","clone-wars-s05e01","clone-wars-s05e14","clone-wars-s05e15","clone-wars-s05e16","clone-wars-s05e17","clone-wars-s05e18","clone-wars-s05e19","clone-wars-s05e20","clone-wars-s06e01","clone-wars-s06e02","clone-wars-s06e03","clone-wars-s06e04","clone-wars-s06e05","clone-wars-s06e06","clone-wars-s06e07","clone-wars-s06e08","clone-wars-s06e09","clone-wars-s06e10","clone-wars-s06e11","clone-wars-s06e12","clone-wars-s06e13","clone-wars-s07e05","clone-wars-s07e06","clone-wars-s07e07","clone-wars-s07e08","clone-wars-s07e01","clone-wars-s07e02","clone-wars-s07e03","clone-wars-s07e04","clone-wars-s07e09","clone-wars-s07e10","clone-wars-s07e11","clone-wars-s07e12"],"caveats":["Relative viewing order only. Sequence numbers are not in-universe years or event timestamps.","The theatrical film follows S2E16 and S1E16. Season 7 episodes 5–8 precede episodes 1–4.","The final arc overlaps Revenge of the Sith, which is outside this collection. No scene-by-scene interleaving is implied.","Legacy story reels and other specials remain excluded from the completed film-and-episode collection."]},{"id":"andor","title":"Andor · episode narrative order","description":"Follow the numbered episodes of seasons 1–2. This preserves the series’ intended narrative presentation rather than sorting its flashbacks into the past.","sourceUrl":"https://www.starwars.com/series/andor","itemIds":["andor-s01e01","andor-s01e02","andor-s01e03","andor-s01e04","andor-s01e05","andor-s01e06","andor-s01e07","andor-s01e08","andor-s01e09","andor-s01e10","andor-s01e11","andor-s01e12","andor-s02e01","andor-s02e02","andor-s02e03","andor-s02e04","andor-s02e05","andor-s02e06","andor-s02e07","andor-s02e08","andor-s02e09","andor-s02e10","andor-s02e11","andor-s02e12"],"caveats":["Episode narrative order is not a complete event chronology: childhood sequences and other flashbacks remain inside their original episodes.","Season 2 uses four three-episode arcs separated by years; individual episodes are not evenly spaced across the timeline.","Rogue One connects the Andor finale to A New Hope. That film is an outside-collection bridge, not a missing Andor episode."]},{"id":"ot","title":"Original trilogy · film narrative order","description":"Follow Episodes IV, V, and VI as complete films: A New Hope, The Empire Strikes Back, then Return of the Jedi.","sourceUrl":"https://www.starwars.com/news/star-wars-movies-and-series-guide","itemIds":["ot-a-new-hope","ot-empire-strikes-back","ot-return-of-the-jedi"],"caveats":["This is film-level narrative order, not a timestamped sequence of simultaneous scenes or journeys.","These three films do not constitute the full Star Wars chronology. Exact in-universe years are not assigned by this sequence."]},{"id":"mandalorian","title":"The Mandalorian · episode narrative order","description":"Follow the numbered episodes of seasons 1–3, with a clearly marked cross-series connection between seasons 2 and 3.","sourceUrl":"https://www.starwars.com/series/the-mandalorian","itemIds":["mandalorian-s01e01","mandalorian-s01e02","mandalorian-s01e03","mandalorian-s01e04","mandalorian-s01e05","mandalorian-s01e06","mandalorian-s01e07","mandalorian-s01e08","mandalorian-s02e01","mandalorian-s02e02","mandalorian-s02e03","mandalorian-s02e04","mandalorian-s02e05","mandalorian-s02e06","mandalorian-s02e07","mandalorian-s02e08","mandalorian-s03e01","mandalorian-s03e02","mandalorian-s03e03","mandalorian-s03e04","mandalorian-s03e05","mandalorian-s03e06","mandalorian-s03e07","mandalorian-s03e08"],"caveats":["Episode narrative order retains flashbacks in their original presentation; it does not place every scene at the episode’s present-day setting.","The Book of Boba Fett chapters 5–7 provide a bridge between season 2 and season 3. Those episodes are outside this collection.","Later-season exact years and elapsed travel times are not assigned. This sequence does not include The Mandalorian and Grogu film."]}]'::jsonb);
CREATE TEMP TABLE desired_sequence_items (sequence_id text,work_id text,position integer,PRIMARY KEY(sequence_id,work_id),UNIQUE(sequence_id,position)) ON COMMIT DROP;
INSERT INTO desired_sequence_items SELECT s.id,i.value,i.ordinality::int FROM desired_sequences s CROSS JOIN LATERAL jsonb_array_elements_text(s.payload->'itemIds') WITH ORDINALITY i(value,ordinality);
DO $catalog$
BEGIN
 IF EXISTS (SELECT 1 FROM atlas_works a LEFT JOIN desired_works d USING(id) WHERE d.id IS NULL OR a.payload IS DISTINCT FROM d.payload OR a.series_id IS DISTINCT FROM d.series_id OR a.kind IS DISTINCT FROM d.kind) THEN RAISE EXCEPTION 'Existing catalog conflicts with reviewed dataset'; END IF;
 IF EXISTS (SELECT 1 FROM atlas_sequences a LEFT JOIN desired_sequences d USING(id) WHERE d.id IS NULL OR a.payload IS DISTINCT FROM d.payload) THEN RAISE EXCEPTION 'Existing sequence conflicts with reviewed dataset'; END IF;
 IF EXISTS (SELECT 1 FROM atlas_sequence_items a LEFT JOIN desired_sequence_items d USING(sequence_id,work_id) WHERE d.work_id IS NULL OR a.position IS DISTINCT FROM d.position) THEN RAISE EXCEPTION 'Existing sequence order conflicts with reviewed dataset'; END IF;
END $catalog$;
INSERT INTO atlas_works SELECT * FROM desired_works ON CONFLICT(id) DO NOTHING;
INSERT INTO atlas_sequences SELECT * FROM desired_sequences ON CONFLICT(id) DO NOTHING;
INSERT INTO atlas_sequence_items SELECT * FROM desired_sequence_items ON CONFLICT(sequence_id,work_id) DO NOTHING;

CREATE TEMP TABLE desired_appearances (work_id text NOT NULL, world_id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(work_id,world_id)) ON COMMIT DROP;
